def main():
    os.makedirs(OUT, exist_ok=True)
    for i, l in enumerate(LANGS):
        with open(os.path.join(OUT, l + '.tsv'), 'w', encoding='utf-8', newline='\n') as f:
            f.write(f'# Galar Native app text, {l}: English TAB translation (generated by dm/android/tools/lang_src.py: edit that file)\n')
            for en, tr in sorted(T.items()): f.write(en.replace('\n', '\\n') + '\t' + tr[i].replace('\n', '\\n') + '\n')
    print(f'{len(T)} texts in {len(LANGS)} languages')
if __name__ == '__main__': main()
